   578	    fn collect_imports(&self, node: Node<'_>, out: &mut BTreeMap<String, String>) {
   579	        match self.language {
   580	            Language::Python => self.collect_python_imports(node, out),
   581	            Language::JavaScript | Language::TypeScript | Language::Tsx => {
   582	                self.collect_js_imports(node, out)
   583	            }
   584	            Language::Go => self.collect_go_imports(node, out),
   585	            _ => {} // C/C++/Rust/Java/Lua/Terraform/Bash: no module-qualified calls
