   589	    fn collect_python_imports(&self, node: Node<'_>, out: &mut BTreeMap<String, String>) {
   590	        match node.kind() {
   591	            // `import utils` or `import utils as u`
   592	            "import_statement" => {
   593	                let mut cursor = node.walk();
   594	                for child in node.children(&mut cursor) {
   595	                    match child.kind() {
   596	                        "dotted_name" => {
   597	                            let name = self.node_text(&child).to_string();
   598	                            // Use last component as alias: `import os.path` → alias "path"
   599	                            let alias = name.rsplit('.').next().unwrap_or(&name).to_string();
   600	                            out.insert(alias, name);
   601	                        }
   602	                        "aliased_import" => {
   603	                            let module = child
   604	                                .child_by_field_name("name")
   605	                                .map(|n| self.node_text(&n).to_string());
   606	                            let alias = child
   607	                                .child_by_field_name("alias")
   608	                                .map(|n| self.node_text(&n).to_string());
   609	                            if let (Some(module), Some(alias)) = (module, alias) {
   610	                                out.insert(alias, module);
   611	                            }
   612	                        }
   613	                        _ => {}
   614	                    }
   615	                }
   616	            }
