   279	/// Scan all files in `ctx` for `g_signal_connect(…, G_CALLBACK(func), …)` calls.
   280	///
   281	/// Returns a map from `func_name → Vec<(registrar_file, call_line)>` so that
   282	/// `to_callers_output` can inject synthetic `CallerRef` entries with
   283	/// `caller_type = "dbus_callback"` and `trust = "untrusted_ipc"` for any
   284	/// diff-touched function that is wired up as a GLib/D-Bus callback.
   285	///
   286	/// Matching is text-level (not AST): finds `G_CALLBACK(` on each line and
   287	/// extracts the identifier inside the parentheses.  This is sufficient for
   288	/// the patterns seen in real D-Bus plugin code.
   289	fn detect_glib_callbacks(
   290	    files: &std::collections::BTreeMap<String, crate::ast::ParsedFile>,
   291	) -> std::collections::BTreeMap<String, Vec<(String, usize)>> {
   292	    use crate::languages::Language;
   293	    let mut map: std::collections::BTreeMap<String, Vec<(String, usize)>> =
   294	        std::collections::BTreeMap::new();
   295	
   296	    for (file_path, parsed) in files {
   297	        if !matches!(parsed.language, Language::C | Language::Cpp) {
   298	            continue;
   299	        }
   300	        for (idx, line_text) in parsed.source.lines().enumerate() {
   301	            let line_num = idx + 1;
   302	            // Find every G_CALLBACK( occurrence on this line.
   303	            // Both `G_CALLBACK(func)` and `G_CALLBACK (func)` forms are common.
   304	            let mut search = line_text;
   305	            while let Some(pos) = search.find("G_CALLBACK") {
   306	                let rest = search[pos + "G_CALLBACK".len()..].trim_start();
   307	                if let Some(rest_after_paren) = rest.strip_prefix('(') {
   308	                    let content = rest_after_paren.trim_start();
   309	                    // Extract the identifier up to ')' or whitespace
   310	                    let end = content
   311	                        .find(|c: char| !c.is_alphanumeric() && c != '_')
   312	                        .unwrap_or(content.len());
   313	                    let func_name = content[..end].trim();
   314	                    if !func_name.is_empty() {
   315	                        map.entry(func_name.to_string())
   316	                            .or_default()
   317	                            .push((file_path.clone(), line_num));
   318	                    }
   319	                }
   320	                // Advance past this match to find any further occurrences.
   321	                search = &search[pos + 1..];
   322	            }
   323	        }
   324	    }
   325	    map
   326	}
