   328	/// Emit the raw reverse call graph for every function touched by the diff.
   329	///
   330	/// For each touched function, performs a BFS through the existing
   331	/// `call_graph.callers` reverse index up to `max_depth` hops.  Cycle-safe
   332	/// via a per-entry visited set.  No algorithm filtering is applied — this is
   333	/// the complete caller set.
   334	pub fn to_callers_output(
   335	    ctx: &crate::cpg::CpgContext,
   336	    diff: &crate::diff::DiffInput,
   337	    max_depth: usize,
   338	) -> CallersOutput {
   339	    use std::collections::{BTreeSet, VecDeque};
