   341	    // Build the GLib/D-Bus callback map once for all touched functions.
   342	    let glib_callbacks = detect_glib_callbacks(ctx.files);
   343	
   344	    let mut entries: Vec<FunctionCallerEntry> = Vec::new();
   345	    let mut seen_touched: BTreeSet<(String, String)> = BTreeSet::new(); // (file, name)
   346	
   347	    for diff_info in &diff.files {
   348	        let parsed = match ctx.files.get(&diff_info.file_path) {
   349	            Some(f) => f,
   350	            None => continue,
   351	        };
   352	        for &line in &diff_info.diff_lines {
   353	            let func_node = match parsed.enclosing_function(line) {
   354	                Some(n) => n,
   355	                None => continue,
   356	            };
   357	            let name_node = match parsed.language.function_name(&func_node) {
   358	                Some(n) => n,
   359	                None => continue,
   360	            };
   361	            let name = parsed.node_text(&name_node).to_string();
   362	            let key = (diff_info.file_path.clone(), name.clone());
   363	            if !seen_touched.insert(key) {
   364	                continue;
   365	            }
   366	            let (start_line, end_line) = parsed.node_line_range(&func_node);
   367	
   368	            // BFS through reverse call graph
