   370	            let mut visited: BTreeSet<(String, String)> = BTreeSet::new(); // (file, name)
   371	            visited.insert((diff_info.file_path.clone(), name.clone()));
   372	            let mut queue: VecDeque<(String, usize)> = VecDeque::new();
   373	            queue.push_back((name.clone(), 0));
   374	
   375	            while let Some((callee_name, depth)) = queue.pop_front() {
   376	                if depth >= max_depth {
   377	                    continue;
   378	                }
   379	                let sites = match ctx.cpg.call_graph.callers.get(&callee_name) {
   380	                    Some(s) => s,
   381	                    None => continue,
   382	                };
