   401	            // `g_signal_connect(…, G_CALLBACK(func), …)` means this function is
   402	            // invoked from the GLib main-loop dispatcher on behalf of unprivileged
   403	            // D-Bus clients — the caller is effectively "untrusted IPC".
   404	            if let Some(registrations) = glib_callbacks.get(&name) {
