   409	                        caller_refs.push(CallerRef {
   410	                            name: "g_signal_connect".to_string(),
   411	                            file: reg_file.clone(),
   412	                            call_line: *reg_line,
   413	                            depth: 1,
   414	                            trust: Some("untrusted_ipc".to_string()),
   415	                            caller_type: Some("dbus_callback".to_string()),
   416	                        });
   417	                    }
