use prism::call_graph::{CallGraph, FunctionId};
use prism::languages::Language;
use prism::repo_loader;
use prism::resolution::{ResolutionConfidence, ResolutionKind};
use std::collections::{BTreeMap, BTreeSet};
use std::env;
use std::path::{Path, PathBuf};

#[derive(Default)]
struct Counts {
    sites: usize,
    edges: usize,
    same_file_sites: usize,
    same_file_edges: usize,
    same_dir_single_sites: usize,
    same_dir_single_edges: usize,
    same_dir_multi_sites: usize,
    same_dir_multi_edges: usize,
    import_bound_sites: usize,
    import_single_sites: usize,
