    py_sites: usize,
    js_sites: usize,
    ts_sites: usize,
    other_sites: usize,
    candidate_fanout: BTreeMap<usize, usize>,
    names: BTreeMap<String, usize>,
    examples: Vec<String>,
}

fn dir_of(path: &str) -> &str { path.rsplit_once('/').map(|(d, _)| d).unwrap_or("") }
fn file_stem(path: &str) -> &str { path.rsplit('/').next().unwrap_or(path).rsplit('.').last().unwrap_or(path) }
fn parent_dir(path: &str) -> Option<&str> { path.rsplit('/').nth(1) }

fn current_import_match<'a>(module_path: &str, ids: &'a [&'a FunctionId]) -> Vec<&'a FunctionId> {
    let module_last = module_path.rsplit('/').next().unwrap_or(module_path);
    let module_stem = module_last.rsplit('.').last().unwrap_or(module_last);
    ids.iter().copied().filter(|fid| {
        let stem_hit = file_stem(&fid.file) == module_stem;
        let dir_hit = parent_dir(&fid.file).map(|d| d == module_last).unwrap_or(false);
        stem_hit || dir_hit
    }).collect()
}

fn resolve_relative_module(caller_file: &str, module_path: &str) -> Option<String> {
    if module_path.starts_with("./") || module_path.starts_with("../") {
        let mut base = PathBuf::from(dir_of(caller_file));
        base.push(module_path);
        let mut parts = Vec::new();
        for comp in base.components() {
            use std::path::Component;
            match comp {
                Component::Normal(s) => parts.push(s.to_string_lossy().to_string()),
                Component::ParentDir => { parts.pop(); },
                Component::CurDir => {},
                _ => {},
            }
        }
        return Some(parts.join("/"));
    }
    if module_path.starts_with('.') {
        let dots = module_path.chars().take_while(|c| *c == '.').count();
        let rest = module_path[dots..].trim_start_matches('.');
        let mut parts: Vec<&str> = dir_of(caller_file).split('/').filter(|s| !s.is_empty()).collect();
        for _ in 1..dots { parts.pop(); }
        let mut out = parts.join("/");
        if !rest.is_empty() {
            if !out.is_empty() { out.push('/'); }
            out.push_str(&rest.replace('.', "/"));
        }
        return Some(out);
    }
    None
}

fn relative_import_match<'a>(caller_file: &str, module_path: &str, ids: &'a [&'a FunctionId]) -> Vec<&'a FunctionId> {
    let Some(base) = resolve_relative_module(caller_file, module_path) else { return Vec::new(); };
    let candidates = [
        format!("{base}.js"), format!("{base}.ts"), format!("{base}.tsx"), format!("{base}.py"),
        format!("{base}/index.js"), format!("{base}/index.ts"), format!("{base}/index.tsx"), format!("{base}/__init__.py"),
    ];
    let set: BTreeSet<String> = candidates.into_iter().collect();
    ids.iter().copied().filter(|fid| set.contains(&fid.file)).collect()
}

fn main() {
    let root = env::args().nth(1).expect("usage: free_multi_analyzer <repo>");
    let loaded = repo_loader::load_repo(Path::new(&root)).expect("load repo");
    let cg = CallGraph::build(&loaded.files);
    let mut c = Counts::default();

    for sites in cg.calls.values() {
        for site in sites {
            let out = cg.resolve_call_site_full(site);
            if out.resolved.is_empty() || !out.resolved.iter().all(|r| r.confidence == ResolutionConfidence::NameOnly && r.kind == ResolutionKind::FreeMulti) {
                continue;
            }
            match Language::from_path(&site.caller.file) {
                Some(Language::Python) => c.py_sites += 1,
                Some(Language::JavaScript) => c.js_sites += 1,
                Some(Language::TypeScript) | Some(Language::Tsx) => c.ts_sites += 1,
                _ => c.other_sites += 1,
            }
            c.sites += 1;
            c.edges += out.resolved.len();
            *c.candidate_fanout.entry(out.resolved.len()).or_default() += 1;
            *c.names.entry(site.callee_name.clone()).or_default() += 1;
            let ids: Vec<&FunctionId> = cg.functions.get(&site.callee_name).into_iter().flat_map(|v| v.iter())
                .filter(|fid| !cg.method_owners.contains_key(*fid))
                .filter(|fid| !cg.static_functions.contains(&(fid.file.clone(), site.callee_name.clone())))
                .collect();
            let same_file: Vec<&FunctionId> = ids.iter().copied().filter(|fid| fid.file == site.caller.file).collect();
            if !same_file.is_empty() { c.same_file_sites += 1; c.same_file_edges += same_file.len(); }
            let same_dir: Vec<&FunctionId> = ids.iter().copied().filter(|fid| dir_of(&fid.file) == dir_of(&site.caller.file)).collect();
            match same_dir.len() { 0 => {}, 1 => { c.same_dir_single_sites += 1; c.same_dir_single_edges += 1; }, n => { c.same_dir_multi_sites += 1; c.same_dir_multi_edges += n; } }
            let import_module = cg.imports.get(&site.caller.file).and_then(|m| m.get(&site.callee_name));
            if let Some(module_path) = import_module {
                c.import_bound_sites += 1;
                let mut matched = current_import_match(module_path, &ids);
                for fid in relative_import_match(&site.caller.file, module_path, &ids) {
                    if !matched.iter().any(|m| m.file == fid.file && m.start_line == fid.start_line) { matched.push(fid); }
                }
                match matched.len() { 0 => c.import_external_sites += 1, 1 => { c.import_single_sites += 1; c.import_single_edges += 1; }, n => { c.import_multi_sites += 1; c.import_multi_edges += n; } }
            } else {
                c.no_import_sites += 1;
                if same_dir.is_empty() { c.no_import_cross_only_sites += 1; c.no_import_cross_only_edges += out.resolved.len(); }
            }
            if c.examples.len() < 20 {
                let module = import_module.cloned().unwrap_or_default();
                let first = ids.first().map(|f| f.file.as_str()).unwrap_or("");
                c.examples.push(format!("{}:{} {}() fanout={} same_file={} same_dir={} import={:?} first={}", site.caller.file, site.line, site.callee_name, out.resolved.len(), same_file.len(), same_dir.len(), if module.is_empty() { None } else { Some(module.as_str()) }, first));
            }
        }
    }
    let mut top_names: Vec<_> = c.names.iter().collect();
    top_names.sort_by_key(|(_, v)| std::cmp::Reverse(**v));
    top_names.truncate(20);
    println!("free_multi_sites={} free_multi_edges={} files={} py_sites={} js_sites={} ts_sites={} other_sites={} same_file_sites={} same_file_edges={} same_dir_single_sites={} same_dir_single_edges={} same_dir_multi_sites={} same_dir_multi_edges={} import_bound_sites={} import_single_sites={} import_single_edges={} import_multi_sites={} import_multi_edges={} import_external_sites={} no_import_sites={} no_import_cross_only_sites={} no_import_cross_only_edges={}", c.sites, c.edges, loaded.files.len(), c.py_sites, c.js_sites, c.ts_sites, c.other_sites, c.same_file_sites, c.same_file_edges, c.same_dir_single_sites, c.same_dir_single_edges, c.same_dir_multi_sites, c.same_dir_multi_edges, c.import_bound_sites, c.import_single_sites, c.import_single_edges, c.import_multi_sites, c.import_multi_edges, c.import_external_sites, c.no_import_sites, c.no_import_cross_only_sites, c.no_import_cross_only_edges);
    println!("candidate_fanout={:?}", c.candidate_fanout);
    println!("top_names={:?}", top_names);
    println!("examples={:?}", c.examples);
}
