   707	
   708	    fn collect_js_import_clause(
   709	        &self,
   710	        node: &Node<'_>,
   711	        module_path: &str,
   712	        out: &mut BTreeMap<String, String>,
   713	    ) {
   714	        let mut cursor = node.walk();
   715	        for child in node.children(&mut cursor) {
   716	            match child.kind() {
   717	                "identifier" => {
   718	                    // Default import: `import utils from './mod'`
   719	                    out.insert(self.node_text(&child).to_string(), module_path.to_string());
   720	                }
   721	                "named_imports" => {
   722	                    // `import { func, other as alias } from './mod'`
   723	                    let mut inner = child.walk();
   724	                    for spec in child.children(&mut inner) {
   725	                        if spec.kind() == "import_specifier" {
   726	                            let name = spec
   727	                                .child_by_field_name("name")
   728	                                .map(|n| self.node_text(&n).to_string());
   729	                            let alias = spec
   730	                                .child_by_field_name("alias")
   731	                                .map(|n| self.node_text(&n).to_string());
   732	                            if let Some(local) = alias.or(name) {
   733	                                out.insert(local, module_path.to_string());
   734	                            }
   735	                        }
   735	                        }
   736	                    }
   737	                }
   738	                "namespace_import" => {
   739	                    // `import * as utils from './mod'`
   740	                    if let Some(id) = child.child_by_field_name("name") {
   741	                        out.insert(self.node_text(&id).to_string(), module_path.to_string());
   742	                    }
