   744	                    let mut inner = child.walk();
   745	                    for c in child.children(&mut inner) {
   746	                        if c.kind() == "identifier" {
   747	                            out.insert(self.node_text(&c).to_string(), module_path.to_string());
   748	                            break;
   749	                        }
   750	                    }
   751	                }
   752	                _ => {}
   753	            }
   754	        }
   755	    }
