   769	                }
   770	            }
   771	            // CommonJS factory calls: `const app = require('fastify')()`.
   772	            // Treat the bound local as importing the required module so framework
   773	            // detection and import-aware sink logic see the canonical binding.
   774	            if self.language.is_call_node(val.kind()) {
   775	                if let Some(func) = val.child_by_field_name("function") {
   776	                    if let Some(path) = self.js_require_call_module_path(&func) {
