   819	    fn js_require_member_binding(&self, node: &Node<'_>) -> Option<(String, String)> {
   820	        if node.kind() != "member_expression" {
   821	            return None;
   822	        }
   823	        let object = node.child_by_field_name("object")?;
   824	        let property = node.child_by_field_name("property")?;
   825	        let module_path = self.js_require_call_module_path(&object)?;
   826	        let member = self
   827	            .node_text(&property)
   828	            .trim_matches(|c| c == '\'' || c == '"' || c == '`')
   829	            .to_string();
   830	        Some((module_path, member))
   831	    }
   832	
   833	    fn js_require_call_module_path(&self, node: &Node<'_>) -> Option<String> {
   834	        if !self.language.is_call_node(node.kind()) {
   835	            return None;
   836	        }
   837	        let func_name = self.language.call_function_name(node)?;
   838	        if self.node_text(&func_name) != "require" {
   839	            return None;
   840	        }
   841	        let args = self.language.call_arguments(node)?;
   842	        let mut cursor = args.walk();
   843	        for child in args.children(&mut cursor) {
   844	            if child.is_named() {
   845	                let text = self.node_text(&child);
   846	                return Some(text.trim_matches(|c| c == '\'' || c == '"').to_string());
   847	            }
   848	        }
   849	        None
   850	    }
   851	
   852	    fn collect_js_require_pattern_bindings(
   853	        &self,
   854	        pattern: &Node<'_>,
   855	        module_path: &str,
   856	        out: &mut BTreeMap<String, String>,
   857	    ) {
   858	        let mut cursor = pattern.walk();
   859	        for child in pattern.children(&mut cursor) {
   860	            match child.kind() {
   861	                "shorthand_property_identifier_pattern" | "identifier" => {
   862	                    out.insert(self.node_text(&child).to_string(), module_path.to_string());
   863	                }
   864	                "pair_pattern" => {
   865	                    if let Some(value) = child.child_by_field_name("value") {
   866	                        if value.kind() == "identifier" {
   867	                            out.insert(self.node_text(&value).to_string(), module_path.to_string());
   868	                        } else if value.kind() == "object_pattern"
   869	                            || value.kind() == "array_pattern"
   870	                        {
   871	                            self.collect_js_require_pattern_bindings(&value, module_path, out);
   872	                        }
   873	                    }
   874	                }
   875	                "rest_pattern" => {
   876	                    let mut inner = child.walk();
   877	                    for inner_child in child.children(&mut inner) {
   878	                        if inner_child.kind() == "identifier" {
   879	                            out.insert(
   880	                                self.node_text(&inner_child).to_string(),
   881	                                module_path.to_string(),
   882	                            );
   883	                        }
   884	                    }
   885	                }
   886	                "object_pattern" | "array_pattern" => {
   887	                    self.collect_js_require_pattern_bindings(&child, module_path, out);
   888	                }
   889	                _ => {}
   890	            }
   891	        }
   892	    }

