    86	/// Derive every distinct call-derived cross-file edge once, keyed
    87	/// `(source_file, target_file) -> reasons` (self-file edges excluded). Shared by
    88	/// `module_deps` (projected to one source file) and `repo_map` (all edges) so the
    89	/// two can never diverge (holistic-review MAJOR).
    90	///
    91	/// NOTE: nav-local call resolution uses documented same-stem behavior for
    92	/// qualified/scoped module hints, so a `utils` qualifier can yield edges to both
    93	/// lib/utils.py and src/utils.py. Deterministic over-reporting is acceptable for
    94	/// the v1 map.
    95	fn collect_module_edges(s: &NavigationSession) -> BTreeMap<(String, String), EdgeReasons> {
    96	    let cg = &s.index.cpg.call_graph;
    97	    let mut edges: BTreeMap<(String, String), EdgeReasons> = BTreeMap::new();
    98	    for (caller, sites) in &cg.calls {
    99	        for site in sites {
   100	            let resolved = crate::navigation::call_resolve::resolve_site_nav(cg, site);
   101	            for edge in resolved {
   102	                let def = edge.target;
   103	                if def.file != caller.file {
   104	                    let score = confidence_score(edge.confidence);
   105	                    let entry = edges
   106	                        .entry((caller.file.clone(), def.file.clone()))
   107	                        .or_default();
   108	                    entry.max_score = entry.max_score.max(score);
   109	                    entry.reasons.insert(ModuleCallReason {
   110	                        callee: site.callee_name.clone(),
   111	                        call_site_line: site.line,
   112	                        qualifier: edge.qualifier,
   113	                        score,
   114	                        kind: edge.kind.as_str().to_string(),
   115	                    });
   116	                }
   117	            }
   118	        }
   119	    }
   120	    edges
   121	}
