   149	fn collect_graph_import_deps(graph: &ScopeGraph, file: &str) -> GraphImportDeps {
   150	    let Some(&file_id) = graph.file_paths.get(file) else {
   151	        return GraphImportDeps::default();
   152	    };
   153	    let mut deps = GraphImportDeps::default();
   154	    for binding in &graph.bindings {
   155	        if !scope_in_file(graph, binding.scope, file_id) {
   156	            continue;
   157	        }
   158	        if !matches!(binding.target, BindTarget::Pending(_, _)) {
   159	            continue;
   160	        }
   161	        match graph_module_dep_edge(graph, GraphImport::Named(binding)) {
   162	            ResolvedImport::File(target) if target != file => {
   163	                deps.files
   164	                    .entry(target)
   165	                    .or_default()
   166	                    .insert(binding.name.clone());
   167	            }
   168	            ResolvedImport::External => {
   169	                deps.external.insert(binding.name.clone());
   170	            }
   171	            ResolvedImport::File(_) | ResolvedImport::Unresolved => {}
   172	        }
   173	    }
   174	    for edge in &graph.edges {
   175	        if edge.kind != EK_GLOB || !scope_in_file(graph, edge.from, file_id) {
   176	            continue;
   177	        }
   178	        match graph_module_dep_edge(graph, GraphImport::Glob(edge)) {
   179	            ResolvedImport::File(target) if target != file => {
   180	                deps.files
   181	                    .entry(target)
   182	                    .or_default()
   183	                    .insert("*".to_string());
   184	            }
   185	            ResolvedImport::External => {
   186	                deps.external.insert("*".to_string());
   187	            }
   188	            ResolvedImport::File(_) | ResolvedImport::Unresolved => {}
   189	        }
   190	    }
   191	    deps
   192	}
