   198	/// Mirrors `nodes_at`'s §5 contract: a skipped or unknown file returns empty
   199	/// `items` + a `SkippedPath` warning - never a hard error.
   200	pub fn module_deps(s: &NavigationSession, file: &str) -> Evidence {
   201	    let query = format!("module-deps:{file}");
   202	    if !s.repo.files.contains_key(file) {
