   208	            .map(|sk| format!("file excluded: {:?}: {file}", sk.reason))
   209	            .unwrap_or_else(|| format!("file not in nav index: {file}"));
   210	        return Evidence {
   211	            query,
   212	            items: vec![],
   213	            truncated: false,
   214	            warnings: vec![Warning {
   215	                kind: WarningKind::SkippedPath,
   216	                message,
   217	                location: Some(Location {
   218	                    file: file.into(),
   219	                    start_line: 1,
   220	                    end_line: 1,
   221	                    start_byte: 0,
   222	                    end_byte: 0,
   223	                }),
   224	            }],
   225	            graph: None,
   226	            reasoning: None,
   227	        };
   228	    }
   229	
   230	    let cg = &s.index.cpg.call_graph;
   231	    // Project the shared edge collector to edges whose SOURCE is the queried file;
   232	    // each distinct target file becomes one PrismCpg item carrying its Calls reasons.
   233	    let mut items = Vec::new();
   234	    for ((source, target), reasons) in collect_module_edges(s) {
   235	        if source != file {
