   237	        }
   238	        let why = reasons
   239	            .reasons
   240	            .iter()
   241	            .flat_map(|reason| {
   242	                std::iter::once(Reason::Calls {
   243	                    callee: reason.callee.clone(),
   244	                    call_site_line: reason.call_site_line,
   245	                    qualifier: reason.qualifier.clone(),
   246	                })
   247	                .chain(std::iter::once(resolution_kind_reason(&reason.kind)))
   248	            })
   249	            .collect();
   250	        items.push(EvidenceItem {
   251	            symbol: None,
   252	            location: Location {
   253	                file: target.clone(),
   254	                start_line: 1,
   255	                end_line: 1,
   256	                start_byte: 0,
   257	                end_byte: 0,
   258	            },
   259	            score: reasons.max_score,
   260	            source: Source::PrismCpg,
   261	            fallback: false,
   262	            why,
   263	            snippet: None,
   264	        });
   265	    }
   266	
   267	    let mut warnings = Vec::new();
   268	    if let Some(graph) = authoritative_rust_scope_graph(s, file) {
   269	        let deps = collect_graph_import_deps(graph, file);
   270	        for (target, modules) in deps.files {
   271	            items.push(EvidenceItem {
   272	                symbol: None,
   273	                location: Location {
   274	                    file: target.clone(),
   275	                    start_line: 1,
   276	                    end_line: 1,
   277	                    start_byte: 0,
   278	                    end_byte: 0,
   279	                },
   280	                score: 1.0,
   280	                score: 1.0,
   281	                source: Source::PrismCpg,
   282	                fallback: false,
   283	                why: modules
   284	                    .into_iter()
   285	                    .map(|module| Reason::ResolvedImport {
   286	                        module,
   287	                        target_file: target.clone(),
   288	                    })
   289	                    .collect(),
   290	                snippet: None,
   291	            });
   292	        }
   293	        for module in &deps.external {
   294	            items.push(EvidenceItem {
   295	                symbol: None,
   296	                location: Location {
   297	                    file: file.into(),
   298	                    start_line: 1,
   299	                    end_line: 1,
   300	                    start_byte: 0,
   301	                    end_byte: 0,
   302	                },
   303	                score: 1.0,
   304	                source: Source::HeuristicImport,
   305	                fallback: false,
   306	                why: vec![Reason::UnresolvedImport {
   307	                    module: module.clone(),
   308	                }],
   309	                snippet: None,
   310	            });
   311	        }
   312	        if !deps.external.is_empty() {
   313	            warnings.push(Warning {
   314	                kind: WarningKind::UnresolvedModule,
   315	                message: format!(
   316	                    "{} module import(s) not filesystem-resolved (v1)",
   317	                    deps.external.len()
   318	                ),
   319	                location: None,
